<script setup lang="ts">
import { ref, watch, computed } from 'vue';
import { ArrowUp, RefreshCw, Upload, Download, FolderPlus, Folder, FileText, Pencil, Trash2, HardDrive, Link, Lock } from 'lucide-vue-next';
import type { Tab, FileEntry } from '../lib/types';
import { call } from '../lib/api';
import { bytes, remoteTime, parentRemote } from '../lib/format';
const props=defineProps<{tab?: Tab; transferCount:number}>();
const emit=defineEmits<{path:[path:string];editor:[file:FileEntry];action:[action:string,file?:FileEntry];upload:[];download:[file:FileEntry];transfers:[]}>();
const files=ref<FileEntry[]>([]);const selected=ref<string>();const pathInput=ref('/');const error=ref('');const loading=ref(false);const filter=ref('');let generation=0;
const current=computed(()=>files.value.find(f=>f.path===selected.value));
const visible=computed(()=>files.value.filter(f=>f.name.toLowerCase().includes(filter.value.toLowerCase())));
async function refresh(){const run=++generation;files.value=[];selected.value=undefined;error.value='';if(props.tab?.status!=='connected'||!props.tab.sessionId){loading.value=false;return;}loading.value=true;try{const result=await call<FileEntry[]>('list_files',{sessionId:props.tab.sessionId,path:props.tab.path});if(run===generation)files.value=result;}catch(e){if(run===generation)error.value=String(e);}finally{if(run===generation)loading.value=false;}}
function navigate(){if(pathInput.value.trim())emit('path',pathInput.value.trim());}
function activate(f:FileEntry){if(f.isDir)emit('path',f.path);else emit('editor',f);}
watch(()=>[props.tab?.id,props.tab?.path,props.tab?.status],()=>{pathInput.value=props.tab?.path||'/';void refresh();},{immediate:true});
defineExpose({refresh});
</script>
<template><section class="file-panel"><div class="file-tabs"><button class="active"><Folder :size="14"/> 文件管理</button><button @click="emit('transfers')"><Upload :size="14"/> 文件传输 <span v-if="transferCount" class="count">{{ transferCount }}</span></button><span class="flex-spacer"/><small>SFTP</small></div>
<div class="file-toolbar"><button class="icon-button" title="上一级" :disabled="tab?.status!=='connected'" @click="emit('path',parentRemote(tab?.path||'/'))"><ArrowUp :size="16"/></button><form class="path-field" @submit.prevent="navigate"><Folder :size="14"/><input v-model="pathInput" aria-label="远端路径" :disabled="tab?.status!=='connected'"/><button class="icon-button" type="submit" title="打开路径"><ArrowUp :size="14" style="transform:rotate(90deg)"/></button></form><button class="icon-button" aria-label="刷新文件" :disabled="loading || tab?.status!=='connected'" @click="refresh"><RefreshCw :size="15" :class="{spinning:loading}"/></button><span class="toolbar-divider"/><button :disabled="tab?.status!=='connected'" @click="emit('upload')"><Upload :size="14"/> 上传</button><button :disabled="!current||current.isDir" @click="current&&emit('download',current)"><Download :size="14"/> 下载</button><button class="icon-button" title="新建文件夹" :disabled="tab?.status!=='connected'" @click="emit('action','mkdir')"><FolderPlus :size="16"/></button><button class="icon-button" title="重命名" :disabled="!current" @click="emit('action','rename',current)"><Pencil :size="14"/></button><button class="icon-button" title="权限" :disabled="!current" @click="emit('action','chmod',current)"><Lock :size="14"/></button><button class="icon-button" title="删除" :disabled="!current" @click="emit('action','delete',current)"><Trash2 :size="14"/></button><input class="file-filter" v-model="filter" placeholder="过滤文件" aria-label="过滤文件"/></div>
<div class="file-table-wrap"><table class="file-table"><thead><tr><th>名称</th><th>大小</th><th>修改时间</th><th>权限</th></tr></thead><tbody><tr v-for="f in visible" :key="f.path" :class="{selected:selected===f.path}" @click="selected=f.path" @dblclick="activate(f)"><td><Folder v-if="f.isDir" :size="16" class="folder-icon"/><Link v-else-if="f.isSymlink" :size="15"/><FileText v-else :size="15"/>{{ f.name }}</td><td>{{ f.isDir?'文件夹':bytes(f.size) }}</td><td>{{ remoteTime(f.modified) }}</td><td>{{ f.permissions!=null?(f.permissions & 0o7777).toString(8):'—' }}</td></tr></tbody></table><div v-if="!visible.length" class="file-empty"><HardDrive :size="25"/><span>{{ loading?'正在读取目录…':error|| (tab?.status==='connected'?'目录为空':'连接服务器后浏览远端文件') }}</span></div></div>
<div class="file-status"><span>{{ files.length }} 个项目</span><span v-if="current">{{ current.name }}</span><span class="flex-spacer"/><span>双击打开文件或目录</span></div></section></template>
